import{_ as t,l,o as a,c as r,v as o,p as c,x as d,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"打开文件表","description":"","frontmatter":{"title":"打开文件表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/file-table.md","filePath":"cs/file-table.md","lastUpdated":1789023840000}'),f={name:"cs/file-table.md"};function h(m,e,_,u,E,B){const i=l("Mermaid");return a(),r("div",null,[e[1]||(e[1]=o('<h1 id="打开文件表" tabindex="-1">打开文件表 <a class="header-anchor" href="#打开文件表" aria-label="Permalink to &quot;打开文件表&quot;">​</a></h1><div class="epigraph"><p>描述符是进程里的整数下标；它指向系统打开文件表的一项，那里才记着偏移与指向 inode 的指针。</p><footer>—— 据 Bach, The Design of the UNIX Operating System；Ritchie and Thompson 的整理</footer></div><p><a href="/cs/file-bytestream">上一课</a>把文件定义为字节流，并点到「偏移在打开文件对象上」。缺口是把这句话收成<strong>三层表</strong>：进程描述符表、系统打开文件表、inode（下一课才展开）。<code>dup</code>、<code>fork</code>、<code>close</code> 的语义全由「谁指向谁」决定，而不是再解释 <code>read</code> 拷贝字节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若偏移存在 inode 上，两个独立 <code>open</code> 会互相移动对方的读写位置。若偏移只存在描述符上，<code>dup</code> 得到的两个整数又应对同一偏移。Unix 折中：描述符表项是指针；打开文件对象（file）持有偏移与状态；多个描述符可指向同一 file；多个 file 可指向同一 inode。缺口不是磁盘格式，而是这张引用图。</p><p>本课不把 <code>O_CLOEXEC</code> 的每一位旗标写完。</p><p><span class="marginnote">fork 复制描述符表，于是父子共享同一批打开文件对象与偏移。exec 可关闭 CLOEXEC 的那些。close 减引用，到零才释放 file。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>open</code>：分配 file，偏移清零，在进程表里找最小空闲整数当 fd。<code>dup</code>：新槽指向同一 file。<code>lseek</code> 改 file 的偏移。独立 <code>open</code> 两次同一路径：两个 file，两个偏移。<a href="/cs/syscall-path">系统调用路径</a>上 <code>read(fd)</code> 只解第一层下标，越界则 EBADF。引用计数保护并发 close。</p>',9)),(a(),c(p,null,{default:d(()=>[s(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22%E8%BF%9B%E7%A8%8B%20fd%20%E8%A1%A8%22%5D%20--%3E%20FILE%5B%22%E6%89%93%E5%BC%80%E6%96%87%E4%BB%B6%3A%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20FILE%20--%3E%20INO%5B%22inode%3A%20%E5%90%8E%E8%AF%BE%22%5D%0A%20%20DUP%5B%22dup%22%5D%20--%3E%20FILE%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三层表让管道、套接字、普通文件共用 fd 空间：file 上的操作向量可以不同，用户只看见整数。这与虚存的 fd 无关——mmap 也抓住同一 file/inode。不要把表写成数据库的连接池；它是进程映像的一部分，随<a href="/cs/process-image">进程</a>复制与退出回收。</p><p>回收器/shrinker 不收缩「打开着的」file；那是引用计数对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 POSIX 的 <code>dup3</code> 全部细节。不把 Windows HANDLE 表当对照考纲。inode 与目录内容下一课才是持久结构；本课允许说「file 指向一个编号对象」。路径如何变成该对象，再下一课查找。</p><p>后课默认：fd 与偏移的共享规则已定。名字查找的缓存，下一课 dentry。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fd → 打开文件（偏移）→ inode；dup 共享偏移，两次 open 不共享。</li><li>fork 复制 fd 表，共享打开实例。</li><li>名字到对象的缓存是 dcache 的缺口。</li><li>出处：Bach, <em>UNIX</em>；Ritchie and Thompson, 1974；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const A=t(f,[["render",h]]);export{b as __pageData,A as default};
